; Block: math

math:
; ---- Subroutine: math.rndseed ----
; source: shared_m68k_math.p8:204

    ALIGN 2

math.rndseed:
            move.b  math.rndseed.seed1+1,math.x1
            move.b  math.rndseed.seed1,math.c1
            move.b  math.rndseed.seed2+1,math.a1
            move.b  math.rndseed.seed2,math.b1
        ; return
    rts
; End of subroutine: math.rndseed

; ---- Subroutine: math.randrangew ----

    ALIGN 2

math.randrangew:
            addq.b  #1,math.x1
            move.b  math.x1,d0
            move.b  math.c1,d1
            eor.b   d1,d0
            move.b  math.a1,d1
            eor.b   d1,d0
            move.b  d0,math.a1
            move.b  d0,d2
            move.b  math.b1,d1
            add.b   d1,d0
            move.b  d0,math.b1
            lsr.b   #1,d0
            eor.b   d2,d0
            move.b  math.c1,d1
            addx.b  d1,d0
            move.b  d0,math.c1
            clr.w   d0
            move.b  math.b1,d0
            lsl.w   #8,d0
            move.b  math.c1,d0
            moveq   #0,d1
            move.w  math.randrangew.n,d1
            mulu.w  d1,d0
            swap    d0
            rts
; End of subroutine: math.randrangew


; ---- Subroutine: math.log2 ----
    ALIGN 2

math.log2:
            move.b  d0,d1
            moveq   #7,d2
        .loop:
            btst    d2,d1
            bne     .found
            subq.b  #1,d2
            bcc     .loop
            moveq   #0,d0
            rts
        .found:
            move.b  d2,d0
            rts
; End of subroutine: math.log2


; ---- Subroutine: math.log2w ----
    ALIGN 2

math.log2w:
            move.w  d0,d1
            moveq   #15,d2
        .loop:
            btst    d2,d1
            bne     .found
            subq.b  #1,d2
            bcc     .loop
            moveq   #0,d0
            rts
        .found:
            move.b  d2,d0
            rts
; End of subroutine: math.log2w


; ---- Subroutine: math.log2l ----
    ALIGN 2

math.log2l:
            move.l  d0,d1
            moveq   #31,d2
        .loop:
            btst    d2,d1
            bne     .found
            subq.b  #1,d2
            bcc     .loop
            moveq   #0,d0
            rts
        .found:
            move.b  d2,d0
            rts
; End of subroutine: math.log2l


; ---- Subroutine: math.lerp ----
    ALIGN 2

math.lerp:
            move.b  d0,d3           ; save v0
            cmp.b   d1,d0
            bcc     .descending
            ; ascending: v1 > v0
            sub.b   d0,d1           ; d1 = delta = v1 - v0
            move.b  d2,d0           ; d0 = t
            and.w   #$ff,d0
            and.w   #$ff,d1
            mulu.w  d1,d0           ; d0 = t * delta
            add.w   #255,d0         ; round up
            lsr.w   #8,d0           ; d0 = upper byte
            add.b   d3,d0           ; result = v0 + upper
            rts
        .descending:
            sub.b   d1,d0           ; d0 = delta = v0 - v1
            move.b  d2,d1           ; d1 = t
            and.w   #$ff,d0
            and.w   #$ff,d1
            mulu.w  d0,d1           ; d1 = t * delta
            add.w   #255,d1         ; round up
            lsr.w   #8,d1           ; d1 = upper byte
            move.b  d3,d0           ; d0 = v0
            sub.b   d1,d0           ; result = v0 - upper
            rts
; End of subroutine: math.lerp


; ---- Subroutine: math.lerpw ----
    ALIGN 2

math.lerpw:
            move.w  d0,d3           ; save v0
            cmp.w   d1,d0
            bcc     .descending
            ; ascending: v1 > v0
            sub.w   d0,d1           ; d1 = delta = v1 - v0
            move.w  d2,d0           ; d0 = t
            mulu.w  d1,d0           ; d0 = t * delta (32-bit)
            move.w  d0,d1           ; d1 = low word
            clr.w   d0              ; d0 = high word << 16
            swap    d0              ; d0 = high word
            tst.w   d1
            beq     .done_asc
            addq.w  #1,d0           ; ceil(product / 65536)
        .done_asc:
            add.w   d3,d0           ; result = v0 + upper
            rts
        .descending:
            sub.w   d1,d0           ; d0 = delta = v0 - v1
            move.w  d2,d1           ; d1 = t
            mulu.w  d0,d1           ; d1 = t * delta (32-bit)
            move.w  d1,d0           ; d0 = low word
            clr.w   d1              ; d1 = high word << 16
            swap    d1              ; d1 = high word
            tst.w   d0
            beq     .done_desc
            addq.w  #1,d1           ; ceil(product / 65536)
        .done_desc:
            move.w  d3,d0           ; d0 = v0
            sub.w   d1,d0           ; result = v0 - upper
            rts
; End of subroutine: math.lerpw


; ---- Subroutine: math.interpolate ----
    ALIGN 2

math.interpolate:
            sub.b   d3,d4           ; d4 = delta_out = outputMax - outputMin (byte)
            sub.b   d1,d0           ; d0 = diff_in = v - inputMin
            and.w   #$ff,d0
            lsl.w   #8,d0           ; d0 = diff_in * 256
            add.b   d2,d0           ; d0 = diff_in * 256 + inputMax (numerator)
            sub.b   d1,d2           ; d2 = denom = inputMax - inputMin
            and.w   #$ff,d2
            and.l   #$ffff,d0       ; clear high word for divu
            divu.w  d2,d0           ; d0 = [remainder:quotient]
            and.w   #$ff,d4
            mulu.w  d4,d0           ; d0 = tmp * delta_out (32-bit)
            lsr.l   #8,d0           ; d0 = high byte of product
            add.b   d3,d0           ; result = msb + outputMin
            rts
; End of subroutine: math.interpolate


; ---- Subroutine: math.interpolatew ----
    ALIGN 2

math.interpolatew:
            sub.w   d3,d4           ; d4 = delta_out = outputMax - outputMin
            sub.w   d1,d0           ; d0 = diff_in = v - inputMin
            mulu.w  d4,d0           ; d0 = diff_in * delta_out (32-bit)
            sub.w   d1,d2           ; d2 = denom = inputMax - inputMin
            divu.w  d2,d0           ; d0 = [remainder:quotient]
            add.w   d3,d0           ; result = outputMin + quotient
            rts
; End of subroutine: math.interpolatew


; ---- Subroutine: math.gcd ----
    ALIGN 2

math.gcd:
            tst.w   d0
            beq     .done_b
            tst.w   d1
            beq     .done_a

            moveq   #0,d2           ; shift = 0

.shift_loop
            move.w  d0,d3
            or.w    d1,d3
            btst    #0,d3
            bne     .shift_done
            lsr.w   #1,d0
            lsr.w   #1,d1
            addq.w  #1,d2
            bra     .shift_loop

.shift_done
            ; remove remaining factors of 2 from a
.a_loop
            btst    #0,d0
            bne     .a_done
            lsr.w   #1,d0
            bra     .a_loop

.a_done
            ; loop while b != 0
.b_outer
            tst.w   d1
            beq     .finish

.b_inner
            btst    #0,d1
            bne     .b_done
            lsr.w   #1,d1
            bra     .b_inner

.b_done
            cmp.w   d1,d0
            bls     .no_swap        ; if a <= b, no swap
            exg     d0,d1           ; swap a and b
.no_swap
            sub.w   d0,d1           ; b = b - a
            bra     .b_outer

.finish
            lsl.w   d2,d0           ; a << shift
.done_a
            rts

.done_b
            move.w  d1,d0
            rts
; End of subroutine: math.gcd

